import { View, Text, Pressable, StyleSheet } from "react-native";
import { useReducer } from "react";
import { registerRootComponent } from "expo";

function reducer(state, action) {
  if (action.type === "add") return state + 1;
  // энд бичнэ үү: "remove" action (0-ээс доош болохгүй)
  return state;
}

function App() {
  const [count, dispatch] = useReducer(reducer, 1);
  return (
    <View style={styles.row}>
      <Pressable nativeID="minus" style={styles.b} onPress={() => dispatch({ type: "remove" })}><Text style={styles.t}>−</Text></Pressable>
      <Text nativeID="count" style={styles.c}>{count}</Text>
      <Pressable nativeID="plus" style={styles.b} onPress={() => dispatch({ type: "add" })}><Text style={styles.t}>+</Text></Pressable>
    </View>
  );
}

const styles = StyleSheet.create({
  row: { flex: 1, flexDirection: "row", gap: 20, alignItems: "center", justifyContent: "center" },
  c: { fontSize: 28, fontWeight: "bold", minWidth: 40, textAlign: "center" },
  b: { backgroundColor: "#2563eb", width: 52, height: 52, borderRadius: 26, alignItems: "center", justifyContent: "center" }, t: { color: "#fff", fontSize: 22, fontWeight: "bold" },
});

registerRootComponent(App);

import { View, Text, Pressable, StyleSheet } from "react-native";
import { useReducer } from "react";
import { registerRootComponent } from "expo";

function reducer(state, action) {
  if (action.type === "add") return state + 1;
  if (action.type === "remove") return Math.max(0, state - 1);
  return state;
}

function App() {
  const [count, dispatch] = useReducer(reducer, 1);
  return (
    <View style={styles.row}>
      <Pressable nativeID="minus" style={styles.b} onPress={() => dispatch({ type: "remove" })}><Text style={styles.t}>−</Text></Pressable>
      <Text nativeID="count" style={styles.c}>{count}</Text>
      <Pressable nativeID="plus" style={styles.b} onPress={() => dispatch({ type: "add" })}><Text style={styles.t}>+</Text></Pressable>
    </View>
  );
}

const styles = StyleSheet.create({
  row: { flex: 1, flexDirection: "row", gap: 20, alignItems: "center", justifyContent: "center" },
  c: { fontSize: 28, fontWeight: "bold", minWidth: 40, textAlign: "center" },
  b: { backgroundColor: "#2563eb", width: 52, height: 52, borderRadius: 26, alignItems: "center", justifyContent: "center" }, t: { color: "#fff", fontSize: 22, fontWeight: "bold" },
});

registerRootComponent(App);
